// Regras do site de evento (as mesmas na criação, no site, no painel, nos avisos e na rotina do dia).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const feT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
// texto longo com parágrafos (história, traje): mantém as quebras
const feTP = (v, max) => String(v ?? '').replace(/\r/g, '').split(/\n{2,}/).map(p => p.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n\n').slice(0, max);
const feEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const feBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const FE_MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const FE_DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
const feDataLonga = d => { const [a, m, dia] = String(d).split('-').map(Number); if (!a) return ''; const dt = new Date(Date.UTC(a, m - 1, dia, 12)); return `${FE_DIAS[dt.getUTCDay()]}, ${dia} de ${FE_MESES[m - 1]} de ${a}`; };
const feDataCurta = d => String(d || '').split('-').reverse().join('/');
const feHora = h => { const m = String(h || '').match(/^(\d{2}):(\d{2})$/); return m ? `${+m[1]}h${m[2] === '00' ? '' : m[2]}` : ''; };
const feQuando = (d, h) => Date.parse(`${d}T${h || '12:00'}:00-03:00`);
const feHoje = (ms = Date.now()) => new Date(ms - 3 * 3600e3).toISOString().slice(0, 10);   // o dia em Brasília
const feDias = (de, ate) => Math.round((Date.parse(ate + 'T12:00:00Z') - Date.parse(de + 'T12:00:00Z')) / 864e5);
const FE_TIPOS = {
  casamento: { nome: 'Casamento', emoji: '💍', de: 'Casamento de' }, aniversario: { nome: 'Aniversário', emoji: '🎂', de: 'Aniversário de' },
  cha: { nome: 'Chá', emoji: '🍼', de: '' }, formatura: { nome: 'Formatura', emoji: '🎓', de: 'Formatura de' }, outro: { nome: 'Evento', emoji: '🎉', de: '' },
};
// paletas: fundo, superfície, texto e cor de destaque; a letra do título (script = cursiva Great Vibes)
const FE_PALETAS = {
  romantico: { nome: 'Romântico', fundo: '#FBF5F3', sup: '#FFFFFF', tx: '#3B2A2E', cor: '#B05A6E', fonte: 'script' },
  classico: { nome: 'Clássico', fundo: '#F6F4EF', sup: '#FFFFFF', tx: '#1F2A3A', cor: '#1F3A5F', fonte: 'serif' },
  rustico: { nome: 'Rústico', fundo: '#F4EFE6', sup: '#FFFDF8', tx: '#3A2E22', cor: '#7A5A3A', fonte: 'script' },
  festa: { nome: 'Festa', fundo: '#FFF8EC', sup: '#FFFFFF', tx: '#2A2140', cor: '#D9481F', fonte: 'sans' },
  elegante: { nome: 'Elegante', fundo: '#14110F', sup: '#211C18', tx: '#F3EDE4', cor: '#C9A45C', fonte: 'serif', escuro: true },
  praia: { nome: 'Praia', fundo: '#F2F8F8', sup: '#FFFFFF', tx: '#173B45', cor: '#23808D', fonte: 'serif' },
};
const feHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const feLum = h => feHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const feContraste = (a, b) => { const x = feLum(a), y = feLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const feMistura = (a, b, k) => { const x = feHex(a), y = feHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cores com contraste garantido: destaque legível no fundo, botão com texto legível, texto apagado ainda legível (4,5:1)
function feTokens(paleta, cor) {
  const p = FE_PALETAS[paleta] || FE_PALETAS.romantico;
  const c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : p.cor;
  const longe = p.escuro ? '#FFFFFF' : '#000000';
  let forte = c;
  for (let i = 0; i < 16 && feContraste(forte, p.fundo) < 4.5; i++) forte = feMistura(forte, longe, 0.12);
  let botao = c, tinta = feContraste('#FFFFFF', c) >= feContraste('#111111', c) ? '#FFFFFF' : '#111111';
  for (let i = 0; i < 16 && feContraste(tinta, botao) < 4.5; i++) botao = feMistura(botao, tinta === '#FFFFFF' ? '#000000' : '#FFFFFF', 0.1);
  let mu = feMistura(p.tx, p.fundo, 0.35);
  for (let i = 0; i < 10 && feContraste(mu, p.fundo) < 4.5; i++) mu = feMistura(mu, p.tx, 0.2);
  return { paleta: paleta in FE_PALETAS ? paleta : 'romantico', nome: p.nome, fundo: p.fundo, sup: p.sup, tx: p.tx, tx2: feMistura(p.tx, p.fundo, 0.15), mu, cor: c, forte, botao, tinta,
    suave: feMistura(c, p.fundo, 0.86), linha: feMistura(c, p.fundo, 0.7), fonte: p.fonte, escuro: !!p.escuro };
}
// Pix copia e cola no padrão BR Code do Banco Central (EMV + CRC16), o mesmo da proposta (D1)
function fePix(chave, nome, cidade, valor, txid) {
  const emv = (id, v) => { const s = String(v); return id + String(s.length).padStart(2, '0') + s; };
  const ascii = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^A-Za-z0-9 ]/g, '').toUpperCase();
  let p = emv('00', '01') + emv('26', emv('00', 'br.gov.bcb.pix') + emv('01', chave)) + emv('52', '0000') + emv('53', '986') + (valor > 0 ? emv('54', valor.toFixed(2)) : '');
  p += emv('58', 'BR') + emv('59', ascii(nome).slice(0, 25) || 'RECEBEDOR') + emv('60', ascii(cidade).slice(0, 15) || 'BRASIL')
    + emv('62', emv('05', String(txid).replace(/[^A-Za-z0-9]/g, '').slice(0, 25) || '***')) + '6304';
  let c = 0xFFFF;
  for (let i = 0; i < p.length; i++) { c ^= p.charCodeAt(i) << 8; for (let j = 0; j < 8; j++) { c = (c & 0x8000) ? ((c << 1) ^ 0x1021) : (c << 1); c &= 0xFFFF; } }
  return p + c.toString(16).toUpperCase().padStart(4, '0');
}
// chave Pix no formato que o banco aceita (CPF/CNPJ com dígito conferido, telefone +55, e-mail, aleatória); '' = inválida
function feChavePix(tipo, v) {
  const s = String(v || '').trim(), d = s.replace(/\D/g, '');
  const dv = (n, pesos) => { const r = n.split('').reduce((a, x, i) => a + Number(x) * pesos[i], 0) % 11; return r < 2 ? 0 : 11 - r; };
  if (tipo === 'cpf') {
    if (d.length !== 11 || /^(\d)\1+$/.test(d)) return '';
    const d1 = dv(d.slice(0, 9), [10, 9, 8, 7, 6, 5, 4, 3, 2]), d2 = dv(d.slice(0, 10), [11, 10, 9, 8, 7, 6, 5, 4, 3, 2]);
    return d1 === +d[9] && d2 === +d[10] ? d : '';
  }
  if (tipo === 'cnpj') {
    if (d.length !== 14 || /^(\d)\1+$/.test(d)) return '';
    const d1 = dv(d.slice(0, 12), [5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]), d2 = dv(d.slice(0, 13), [6, 5, 4, 3, 2, 9, 8, 7, 6, 5, 4, 3, 2]);
    return d1 === +d[12] && d2 === +d[13] ? d : '';
  }
  if (tipo === 'telefone') { const n = (d.length === 12 || d.length === 13) && d.startsWith('55') ? d : '55' + d; return n.length === 12 || n.length === 13 ? '+' + n : ''; }
  if (tipo === 'email') return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(s) ? s.toLowerCase().slice(0, 77) : '';
  if (tipo === 'aleatoria') return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(s) ? s.toLowerCase() : '';
  return '';
}
// ───── trava: frase com horário, data, valor ou serviço que o anfitrião não informou sai do texto ─────
const FE_SERVICOS = ['open bar', 'bar liberado', 'bebida liberada', 'buffet', 'churrasco', 'jantar', 'almoço', 'coquetel', 'dj', 'banda', 'show', 'transfer', 'translado',
  'van', 'ônibus', 'hospedagem', 'hotel', 'pousada', 'estacionamento', 'manobrista', 'valet', 'fotógrafo', 'cabine de fotos', 'piscina', 'recreação', 'monitores',
  'espaço kids', 'brinquedoteca', 'lembrancinha', 'chuva de arroz', 'cerimônia religiosa', 'igreja', 'missa', 'culto'];
const feHoraNorm = s => { const m = String(s).match(/(\d{1,2})\s*(?:h|:)\s*(\d{2})?/i); return m ? `${+m[1]}:${m[2] || '00'}` : ''; };
function feFatos(ev) {
  const horas = new Set([ev.hora, ev.hora_fim, ...(ev.locais || []).map(l => l.hora)].filter(Boolean).map(feHoraNorm));
  const dias = new Set(), nums = new Set();
  [ev.data, ev.rsvp && ev.rsvp.prazo].filter(Boolean).forEach(d => { const [a, m, dia] = d.split('-').map(Number); dias.add(`${dia} de ${FE_MESES[m - 1]}`); dias.add(`${dia}/${m}`); });
  ((ev.presentes && ev.presentes.itens) || []).forEach(g => { nums.add(Math.round(g.valor * 100)); nums.add(Math.round(g.valor * g.cotas * 100)); });
  const base = [ev.anfitrioes, ev.titulo, ev.dados && ev.dados.historia, ev.dados && ev.dados.traje, ev.dados && ev.dados.informacoes,
    ...(ev.locais || []).map(l => `${l.titulo} ${l.nome} ${l.endereco}`), ...((ev.presentes && ev.presentes.itens) || []).map(g => g.nome)].join(' ').toLowerCase();
  return { horas, dias, nums, base };
}
function feGuarda(txt, fatos, onde, problemas) {
  return String(txt || '').split(/\n{2,}/).map(par => feGuardaPar(par, fatos, onde, problemas)).filter(Boolean).join('\n\n');
}
function feGuardaPar(par, fatos, onde, problemas) {
  const frases = String(par || '').split(/(?<=[.!?…])\s+/);
  const fica = frases.filter(f => {
    const l = f.toLowerCase();
    const hs = (l.match(/\b\d{1,2}\s?(?:h\s?\d{0,2}|:\d{2})(?![\w%])/g) || []).map(feHoraNorm).filter(h => !fatos.horas.has(h));
    const ds = (l.match(/\b\d{1,2}\s+de\s+(?:janeiro|fevereiro|março|abril|maio|junho|julho|agosto|setembro|outubro|novembro|dezembro)\b/g) || []).map(x => x.replace(/\s+/g, ' ')).filter(x => !fatos.dias.has(x))
      .concat((l.match(/\b\d{1,2}\/\d{1,2}(?:\/\d{2,4})?\b/g) || []).map(x => x.split('/').slice(0, 2).map(Number).join('/')).filter(x => !fatos.dias.has(x)));
    const vs = (f.match(/R\$\s?\d[\d.]*(?:,\d{1,2})?/g) || []).map(x => Math.round(Number(x.replace(/[^\d,]/g, '').replace(',', '.')) * 100)).filter(n => !fatos.nums.has(n));
    const ss = FE_SERVICOS.filter(s => new RegExp(`(^|[^a-zà-ú])${s}([^a-zà-ú]|$)`).test(l) && !fatos.base.includes(s));
    const ruim = [...hs.map(h => 'horário ' + h), ...ds.map(d => 'data ' + d), ...vs.map(v => 'valor ' + feBRL(v / 100)), ...ss.map(s => '"' + s + '"')];
    if (ruim.length && problemas) problemas.push(`${onde}: tirei a frase com ${ruim.join(', ')} que não está nos dados ("${feT(f, 80)}")`);
