}
// textos da redatora (ou da revisora) no formato que o site usa, com tamanho máximo e o que faltar preenchido
function feTextos(r, V) {
  r = r || {};
  const d = V.dados, T = FE_TIPOS[d.tipo] || FE_TIPOS.outro, o = x => (x && typeof x === 'object' ? x : {});
  const cp = o(r.capa), hi = o(r.historia), tr = o(r.traje), rv = o(r.rsvp), pr = o(r.presentes), mu = o(r.mural), cv = o(r.convite), le = o(r.lembretes), im = o(r.imagens);
  const casal = d.tipo === 'casamento';
  return {
    capa: { titulo: feT(cp.titulo, 80) || d.titulo, subtitulo: feT(cp.subtitulo, 160) || (casal ? 'Vamos nos casar e queremos você com a gente!' : 'Queremos você com a gente nesse dia!'), chamada: feT(cp.chamada, 40) || 'Confirmar presença' },
    historia: { titulo: feT(hi.titulo, 60) || (casal ? 'Nossa história' : 'Sobre o dia'), texto: feTP(hi.texto, 1800) || feTP(d.historia, 1800) },
    traje: { titulo: feT(tr.titulo, 40) || 'Traje', texto: feTP(tr.texto, 400) || d.traje },
    faq: (Array.isArray(r.faq) ? r.faq : []).map(x => ({ p: feT(x && x.p, 120), r: feT(x && x.r, 400) })).filter(x => x.p && x.r).slice(0, 8),
    rsvp: { titulo: feT(rv.titulo, 60) || 'Confirme sua presença', texto: feT(rv.texto, 220) || 'Conte para a gente se você vem. Assim preparamos tudo com carinho.',
      obrigado: feT(rv.obrigado, 200) || 'Presença confirmada! Que alegria ter você com a gente.', recusa: feT(rv.recusa, 200) || 'Que pena! Obrigado por avisar, vamos sentir sua falta.' },
    presentes: { titulo: feT(pr.titulo, 60) || 'Lista de presentes', texto: feT(pr.texto, 300) || 'Se quiser nos presentear, escolha uma cota: o Pix vai direto para nós.' },
    mural: { titulo: feT(mu.titulo, 60) || 'Mural de recados', texto: feT(mu.texto, 200) || 'Deixe uma mensagem carinhosa: ela aparece aqui para todos.' },
    convite: { chamada: feT(cv.chamada, 60) || (T.de ? T.de : 'Você é nosso convidado'), texto: feT(cv.texto, 160) || 'Contamos com a sua presença.', rodape: feT(cv.rodape, 80) || 'Confirme pelo QR ou pelo link' },
    mensagem_whatsapp: feT(r.mensagem_whatsapp, 400) || `Oi! Você é nosso convidado: ${d.titulo}, ${feDataLonga(d.data)}. Veja tudo e confirme sua presença aqui: {link}`,
    lembretes: { semana: feT(le.semana, 140) || `Falta 1 semana para ${d.titulo}! Já confirmou sua presença?`, vespera: feT(le.vespera, 140) || `É amanhã! ${d.titulo} começa às ${feHora(d.hora)}.`,
      dia: feT(le.dia, 140) || `É hoje! Esperamos você às ${feHora(d.hora)}.` },
