    `SUMMARY:${esc(ev.titulo)}`, `LOCATION:${esc([l.nome, l.endereco].filter(Boolean).join(' - '))}`, `DESCRIPTION:${esc(link)}`, 'BEGIN:VALARM', 'TRIGGER:-P1D', 'ACTION:DISPLAY',
    `DESCRIPTION:${esc(ev.titulo)} é amanhã`, 'END:VALARM', 'END:VEVENT', 'END:VCALENDAR'].join('\r\n');
