// Confere a chave do painel e decide o que fazer: confirmar/cancelar presente, aprovar/ocultar recado, pedir texto de aviso à IA,
// mandar o aviso (faixa no site + celulares) ou o resumo para o buffet.
const P = $('🧩 Lê o pedido do dono').first().json;
let ev = null, avisos = [];
try { ev = JSON.parse($('📖 Lê o evento (dono)').first().json.evento || 'null'); } catch (e) {}
try { avisos = JSON.parse($('📖 Lê os avisos (dono)').first().json.avisos || '[]'); } catch (e) {}
const ANO = 34560000;   // 400 dias
const responde = (codigo, corpo) => [{ json: { rota: 'responder', codigo, resposta: JSON.stringify(corpo), sets: [] } }];
if (!ev) return responde(404, { ok: false, erro: 'Evento não encontrado.' });
if (!P.chave || P.chave !== ev.chave) return responde(403, { ok: false, erro: 'Chave errada. Use o link do painel que apareceu quando você criou o site.' });
const agora = Date.now();
const grava = (chave, obj, corpo) => [{ json: { rota: 'gravar', codigo: 200, resposta: JSON.stringify(corpo), sets: [{ chave, valor: JSON.stringify(obj), ttl: ANO }] } }];
if (P.acao === 'presente') {
  const r = feLeChaves($('🗂️ Lê as reservas (dono)').first().json, `fep:${ev.id}:`).find(x => x.pid === P.pid);
  if (!r) return responde(404, { ok: false, erro: 'Reserva não encontrada.' });
  if (!['confirmado', 'cancelado', 'reservado'].includes(P.status)) return responde(400, { ok: false, erro: 'Situação inválida.' });
  const chave = r._chave; delete r._chave;
  return grava(chave, { ...r, status: P.status, mudou_em: agora, ...(P.status === 'reservado' ? { quando: agora } : {}) }, { ok: true, pid: r.pid, status: P.status });
}
if (P.acao === 'recado') {
  const m = feLeChaves($('🗂️ Lê os recados (dono)').first().json, `fem:${ev.id}:`).find(x => x.mid === P.mid);
  if (!m) return responde(404, { ok: false, erro: 'Recado não encontrado.' });
  if (!['aprovado', 'oculto'].includes(P.status)) return responde(400, { ok: false, erro: 'Situação inválida.' });
  const chave = m._chave; delete m._chave;
  return grava(chave, { ...m, status: P.status, motivo: P.status === 'aprovado' ? 'aprovado pelo anfitrião' : 'ocultado pelo anfitrião' }, { ok: true, mid: m.mid, status: P.status });
}
const fatos = `EVENTO: ${ev.titulo} — ${feDataLonga(ev.data)} às ${feHora(ev.hora)}
LOCAIS: ${ev.locais.map(l => `${l.titulo}: ${l.nome}${l.endereco ? ' (' + l.endereco + ')' : ''}${l.hora ? ' às ' + feHora(l.hora) : ''}`).join(' · ')}`;
if (P.acao === 'aviso_ia') {
  const rascunho = feT(P.texto, 600);
  if (rascunho.length < 5) return responde(400, { ok: false, erro: 'Escreva o aviso (pode ser do seu jeito: a IA arruma).' });
  return [{ json: { rota: 'aviso_ia', codigo: 200, sets: [], rascunho, texto_ia: `${fatos}\n\nRASCUNHO DO ANFITRIÃO (a informação nova está aqui e vale mais que os dados antigos):\n${rascunho}` } }];
}
if (P.acao === 'aviso') {
  const titulo = feT(P.titulo, 60).replace(/[<>{}]/g, ''), texto = feT(P.texto, 300).replace(/[<>{}]/g, '');
  if (titulo.length < 3 || texto.length < 5) return responde(400, { ok: false, erro: 'Escreva o título e o texto do aviso.' });
  const novo = [{ titulo, texto, quando: agora }, ...avisos].slice(0, 30);
  return [{ json: { rota: 'avisar', codigo: 200, sets: [], titulo, texto, avisos: JSON.stringify(novo), payload: JSON.stringify({ titulo, texto, url: 'convite', tag: 'aviso-' + agora }) } }];
}
if (P.acao === 'buffet') {
  const rs = feLeChaves($('🗂️ Lê as respostas (dono)').first().json, `fer:${ev.id}:`).filter(r => r.vem === 'sim');
  const pessoas = rs.reduce((a, r) => a + (r.pessoas || 0), 0), criancas = rs.reduce((a, r) => a + (r.criancas || 0), 0);
