  // cada texto escrito vira um item (o mesmo texto de vários convites conta junto); a IA só diz o grupo de cada texto, a conta é do código
  const textos = [];
  com.forEach(r => r.restricoes.forEach(t => {
    const k = String(t).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/\s+/g, ' ').trim();
    const x = textos.find(y => y.k === k);
    if (x) { if (!x.convites.includes(r.nome)) x.convites.push(r.nome); } else textos.push({ k, texto: t, convites: [r.nome] });
  }));
  const linhas = textos.map((x, i) => `${i + 1}. ${x.texto} (${x.convites.length} convite${x.convites.length > 1 ? 's' : ''})`).join('\n');
  return [{ json: { rota: 'buffet', codigo: 200, sets: [], numeros: { pessoas, adultos: pessoas - criancas, criancas, convites: rs.length, com_restricao: com.length },
    textos: textos.map(x => ({ texto: x.texto, convites: x.convites })), titulo: ev.titulo,
    texto_ia: `${fatos}\nCONFIRMADOS: ${pessoas} pessoas (${pessoas - criancas} adultos e ${criancas} crianças) em ${rs.length} convites.\nRESTRIÇÕES ESCRITAS PELOS CONVIDADOS (cada linha é um texto):\n${linhas || '(nenhuma)'}` } }];
}
return responde(400, { ok: false, erro: 'Ação desconhecida.' });

