  'espaço kids', 'brinquedoteca', 'lembrancinha', 'chuva de arroz', 'cerimônia religiosa', 'igreja', 'missa', 'culto'];
const feHoraNorm = s => { const m = String(s).match(/(\d{1,2})\s*(?:h|:)\s*(\d{2})?/i); return m ? `${+m[1]}:${m[2] || '00'}` : ''; };
