function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Resumo para o buffet: os NÚMEROS saem da conta (nunca da IA). A IA só diz o grupo de cada texto escrito ("não como carne" ➜ Vegetariana);
// o código junta os convites de cada grupo. Texto que a IA não classificou vira um grupo com o próprio nome.
