// reservas de presente que seguram cota: confirmada, "já paguei" ou reservada há menos de 48 h (depois disso a cota volta)
const FE_RESERVA_H = 48;
const feReservaVale = (r, agora = Date.now()) => r && (r.status === 'confirmado' || r.status === 'pago_informado' || (r.status === 'reservado' && agora - r.quando < FE_RESERVA_H * 3600e3));
