// Rotina do dia: quais eventos têm lembrete hoje ("falta 1 semana", "é amanhã", "é hoje"), pelo dia em Brasília.
const hoje = feHoje();
const TIPO = { 7: 'semana', 1: 'vespera', 0: 'dia' };
const lista = Object.entries($input.first().json || {}).filter(([k, v]) => k.startsWith('fe:idx:') && /^\d{4}-\d{2}-\d{2}$/.test(String(v)))
  .map(([k, v]) => ({ id: k.slice(7), tipo: TIPO[feDias(hoje, String(v))] })).filter(x => x.tipo && /^[a-z0-9-]{4,64}$/.test(x.id));
