const saida = [], invalidos = [];
eventos.forEach((e, i) => {
  const marca = Number(Object.values((marcas[i] || {}).json || {})[0]) || 0;
  let ev = null;
  try { ev = JSON.parse(e.json.evento || 'null'); } catch (x) {}
  if (!ev || marca !== 1) return;
  const payload = JSON.stringify({ titulo: TITULO[e.json.tipo], texto: ev.textos.lembretes[e.json.tipo], url: 'convite', tag: 'lembrete-' + e.json.tipo });
  Object.entries((inscritos[i] || {}).json || {}).filter(([k]) => k.startsWith(`fepush:${ev.id}:`)).forEach(([chave, v]) => {
    let sub = null;
    try { sub = JSON.parse(v); } catch (x) {}
    if (!sub || !sub.endpoint || !sub.keys) return;
    try {
      saida.push({ json: { chave, id: ev.id, tipo: e.json.tipo, endpoint: sub.endpoint, autorizacao: vapid(ev, sub.endpoint) },
        binary: { corpo: { data: criptografa(sub, payload).toString('base64'), mimeType: 'application/octet-stream', fileName: 'lembrete.bin' } } });
    } catch (x) { invalidos.push(chave); }
  });
