// Conta quantos celulares receberam. 2xx = entregue · 404/410 = a pessoa desinstalou ou desligou os avisos (sai da lista) · outro = falha.
const envios = $('🧩 Prepara os lembretes').all();
const respostas = $input.all();
let entregues = 0;
const vencidos = [], falhas = [];
respostas.forEach((r, i) => {
  const st = Number(r.json.statusCode || 0);
  if (st >= 200 && st < 300) entregues++;
  else if (st === 404 || st === 410) vencidos.push(envios[i] ? envios[i].json.chave : '');
  else falhas.push(st || 'erro');
