<ul id="m-lista">${recados.length ? recados.map(m => `<li><p>${E(m.texto)}</p><cite>${E(m.nome)} · ${E(new Date(m.quando - 3 * 3600e3).toISOString().slice(8, 10) + '/' + new Date(m.quando - 3 * 3600e3).toISOString().slice(5, 7))}</cite></li>`).join('') : '<li id="m-vazio"><p>Seja a primeira pessoa a deixar um recado! 💛</p></li>'}</ul></section>` : ''}
${t.faq.length ? `<section id="duvidas"><h2>Dúvidas</h2>${t.faq.map(f => `<details><summary>${E(f.p)}</summary><p>${E(f.r)}</p></details>`).join('')}</section>` : ''}
