return [{ json: { codigo: 200, html } }];

// Monta o service worker: o "motor" do convite no celular (abre sem internet e mostra os avisos dos anfitriões).
const id = String(($('🔔 Pedido do motor (GET)').first().json.params || {}).id || '').replace(/[^a-z0-9-]/g, '');

function motor(ID) {
  var CACHE = 'fe-' + ID + '-v1';
  var TELAS = ['convite', 'convite-manifesto', 'convite-icone?t=192', 'convite-icone?t=512'];
  self.addEventListener('install', function (e) {
    e.waitUntil(caches.open(CACHE).then(function (c) { return c.addAll(TELAS); }).then(function () { return self.skipWaiting(); }));
  });
  self.addEventListener('activate', function (e) {
    e.waitUntil(caches.keys().then(function (ks) {
      return Promise.all(ks.filter(function (k) { return k.indexOf('fe-' + ID + '-') === 0 && k !== CACHE; }).map(function (k) { return caches.delete(k); }));
    }).then(function () { return self.clients.claim(); }));
  });
  // internet primeiro (cotas, recados e avisos mudam); sem internet, mostra a última versão guardada
  self.addEventListener('fetch', function (e) {
    var url = new URL(e.request.url);
    if (e.request.method !== 'GET' || url.origin !== location.origin || url.pathname.indexOf(self.registration.scope.replace(location.origin, '')) !== 0) return;
    e.respondWith(fetch(e.request).then(function (r) {
      if (r.ok) { var copia = r.clone(); caches.open(CACHE).then(function (c) { c.put(e.request, copia); }); }
      return r;
    }).catch(function () {
      return caches.match(e.request, { ignoreSearch: url.pathname.slice(-7) === 'convite' }).then(function (r) { return r || caches.match('convite'); });
    }));
  });
  self.addEventListener('push', function (e) {
    var d = {};
    try { d = e.data ? e.data.json() : {}; } catch (x) { d = { texto: e.data ? e.data.text() : '' }; }
    e.waitUntil(self.registration.showNotification(d.titulo || 'Aviso do evento', {
      body: d.texto || '', icon: 'convite-icone?t=192', badge: 'convite-icone?t=96', tag: d.tag || 'aviso', data: { url: d.url || 'convite' },
    }));
  });
  self.addEventListener('notificationclick', function (e) {
    e.notification.close();
    var alvo = new URL(e.notification.data && e.notification.data.url || 'convite', self.registration.scope).href;
    e.waitUntil(self.clients.matchAll({ type: 'window', includeUncontrolled: true }).then(function (ws) {
      for (var i = 0; i < ws.length; i++) { if (ws[i].url.indexOf(self.registration.scope) === 0 && 'focus' in ws[i]) { ws[i].navigate(alvo); return ws[i].focus(); } }
      return self.clients.openWindow(alvo);
    }));
  });
}
return [{ json: { js: id ? `(${motor.toString()})(${JSON.stringify(id)});` : '/* convite inválido */' } }];

// O "RG" do convite: nome, ícone e cores que o celular usa ao instalar.
let ev = null;
try { ev = JSON.parse($('📖 Lê o evento (manifesto)').first().json.evento || 'null'); } catch (e) {}
if (!ev) return [{ json: { codigo: 404, manifesto: '{}' } }];
const m = {
  id: 'fe-' + ev.id, name: ev.titulo, short_name: ev.anfitrioes.slice(0, 12).trim(), description: (ev.textos && ev.textos.capa.subtitulo) || ev.titulo, lang: 'pt-BR',
  start_url: 'convite?origem=app', scope: './', display: 'standalone', orientation: 'portrait',
  background_color: ev.cores.fundo, theme_color: ev.cores.botao,
  icons: [
    { src: 'convite-icone?t=192', sizes: '192x192', type: 'image/png', purpose: 'any' },
    { src: 'convite-icone?t=512', sizes: '512x512', type: 'image/png', purpose: 'any' },
    { src: 'convite-icone?t=512&m=1', sizes: '512x512', type: 'image/png', purpose: 'maskable' },
  ],
};
return [{ json: { codigo: 200, manifesto: JSON.stringify(m) } }];

// Calcula o ícone do app: fundo na cor do evento + iniciais dos anfitriões ("m=1" = ícone que o Android recorta em círculo: letras menores).
const q = $('🔔 Pedido do ícone (GET)').first().json.query || {};
let ev = null;
try { ev = JSON.parse($('📖 Lê o evento (ícone)').first().json.evento || 'null'); } catch (e) {}
const t = [96, 144, 180, 192, 512].includes(Number(q.t)) ? Number(q.t) : 192;
const recorte = q.m === '1';
const ini = (ev ? ev.iniciais : '?').slice(0, 2);
const fonte = Math.round(t * (recorte ? 0.3 : 0.4) * (ini.length === 1 ? 1.15 : 1));
const largura = fonte * 0.74 * ini.length; // Verdana Bold: cada maiúscula ocupa ~0,74 da altura
return [{ json: { tamanho: t, cor: ev ? ev.cores.botao : '#9d4b5b', letra: ev ? ev.cores.tinta : '#ffffff', iniciais: ini, fonte, x: Math.round((t - largura) / 2), y: Math.round(t / 2 + fonte * 0.36) } }];

// Lê o pedido do convidado (a página manda como texto). O código da resposta sai do telefone: o mesmo número responde de novo = atualiza.
const crypto = require('crypto');
const w = $('🔔 Resposta do convidado (POST)').first().json;
let b = w.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const h = w.headers || {};
const id = String(b.id || '').replace(/[^a-z0-9-]/g, '').slice(0, 64) || 'nenhum';
let zap = String(b.whatsapp || '').replace(/\D/g, '');
if (zap.length === 10 || zap.length === 11) zap = '55' + zap;
const rid = crypto.createHash('sha256').update(id + ':' + zap).digest('hex').slice(0, 16);
const ip = String(h['x-real-ip'] || String(h['x-forwarded-for'] || 'sem-ip').split(',')[0]).trim().replace(/[^0-9a-fA-F.:]/g, '').slice(0, 45) || 'sem-ip';
return [{ json: { ...b, id, zap, rid, ip } }];

// Regras do site de evento (as mesmas na criação, no site, no painel, nos avisos e na rotina do dia).
// corta no fim de uma frase (ou de uma palavra, com "…"): nunca no meio da palavra
const feT = (v, max) => {
  const s = String(v ?? '').replace(/\s+/g, ' ').trim();
  if (s.length <= max) return s;
  const c = s.slice(0, max), fim = Math.max(c.lastIndexOf('. '), c.lastIndexOf('! '), c.lastIndexOf('? '));
  if (fim >= max * 0.55) return c.slice(0, fim + 1);
  const esp = c.lastIndexOf(' ');
  return (esp >= max * 0.55 ? c.slice(0, esp) : c.slice(0, max - 1)).replace(/[\s,;:.–—-]+$/, '') + '…';
};
// texto longo com parágrafos (história, traje): mantém as quebras
const feTP = (v, max) => String(v ?? '').replace(/\r/g, '').split(/\n{2,}/).map(p => p.replace(/\s+/g, ' ').trim()).filter(Boolean).join('\n\n').slice(0, max);
const feEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const feBRL = n => 'R$ ' + Number(n || 0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const FE_MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const FE_DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
const feDataLonga = d => { const [a, m, dia] = String(d).split('-').map(Number); if (!a) return ''; const dt = new Date(Date.UTC(a, m - 1, dia, 12)); return `${FE_DIAS[dt.getUTCDay()]}, ${dia} de ${FE_MESES[m - 1]} de ${a}`; };
const feDataCurta = d => String(d || '').split('-').reverse().join('/');
const feHora = h => { const m = String(h || '').match(/^(\d{2}):(\d{2})$/); return m ? `${+m[1]}h${m[2] === '00' ? '' : m[2]}` : ''; };
const feQuando = (d, h) => Date.parse(`${d}T${h || '12:00'}:00-03:00`);
const feHoje = (ms = Date.now()) => new Date(ms - 3 * 3600e3).toISOString().slice(0, 10);   // o dia em Brasília
const feDias = (de, ate) => Math.round((Date.parse(ate + 'T12:00:00Z') - Date.parse(de + 'T12:00:00Z')) / 864e5);
const FE_TIPOS = {
  casamento: { nome: 'Casamento', emoji: '💍', de: 'Casamento de' }, aniversario: { nome: 'Aniversário', emoji: '🎂', de: 'Aniversário de' },
  cha: { nome: 'Chá', emoji: '🍼', de: '' }, formatura: { nome: 'Formatura', emoji: '🎓', de: 'Formatura de' }, outro: { nome: 'Evento', emoji: '🎉', de: '' },
};
// paletas: fundo, superfície, texto e cor de destaque; a letra do título (script = cursiva Great Vibes)
const FE_PALETAS = {
  romantico: { nome: 'Romântico', fundo: '#FBF5F3', sup: '#FFFFFF', tx: '#3B2A2E', cor: '#B05A6E', fonte: 'script' },
  classico: { nome: 'Clássico', fundo: '#F6F4EF', sup: '#FFFFFF', tx: '#1F2A3A', cor: '#1F3A5F', fonte: 'serif' },
  rustico: { nome: 'Rústico', fundo: '#F4EFE6', sup: '#FFFDF8', tx: '#3A2E22', cor: '#7A5A3A', fonte: 'script' },
  festa: { nome: 'Festa', fundo: '#FFF8EC', sup: '#FFFFFF', tx: '#2A2140', cor: '#D9481F', fonte: 'sans' },
  elegante: { nome: 'Elegante', fundo: '#14110F', sup: '#211C18', tx: '#F3EDE4', cor: '#C9A45C', fonte: 'serif', escuro: true },
  praia: { nome: 'Praia', fundo: '#F2F8F8', sup: '#FFFFFF', tx: '#173B45', cor: '#23808D', fonte: 'serif' },
};
const feHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const feLum = h => feHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const feContraste = (a, b) => { const x = feLum(a), y = feLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const feMistura = (a, b, k) => { const x = feHex(a), y = feHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cores com contraste garantido: destaque legível no fundo, botão com texto legível, texto apagado ainda legível (4,5:1)
function feTokens(paleta, cor) {
  const p = FE_PALETAS[paleta] || FE_PALETAS.romantico;
  const c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : p.cor;
  const longe = p.escuro ? '#FFFFFF' : '#000000';
