// Confere a chave do painel e decide o que fazer: confirmar/cancelar presente, aprovar/ocultar recado, pedir texto de aviso à IA,
// mandar o aviso (faixa no site + celulares) ou o resumo para o buffet.
const P = $('🧩 Lê o pedido do dono').first().json;
let ev = null, avisos = [];
try { ev = JSON.parse($('📖 Lê o evento (dono)').first().json.evento || 'null'); } catch (e) {}
try { avisos = JSON.parse($('📖 Lê os avisos (dono)').first().json.avisos || '[]'); } catch (e) {}
const ANO = 34560000;   // 400 dias
const responde = (codigo, corpo) => [{ json: { rota: 'responder', codigo, resposta: JSON.stringify(corpo), sets: [] } }];
if (!ev) return responde(404, { ok: false, erro: 'Evento não encontrado.' });
if (!P.chave || P.chave !== ev.chave) return responde(403, { ok: false, erro: 'Chave errada. Use o link do painel que apareceu quando você criou o site.' });
const agora = Date.now();
