// Prepara os lembretes do dia para cada celular inscrito. A marca (1ª vez = 1) garante um lembrete só, mesmo se a rotina rodar duas vezes.
const eventos = $('📖 Lê o evento (rotina)').all(), inscritos = $('🗂️ Lê os inscritos (rotina)').all(), marcas = $('🧮 Marca o lembrete').all();
const TITULO = { semana: 'Falta 1 semana! 💛', vespera: 'É amanhã! 🎉', dia: 'É hoje! 🎉' };
const saida = [], invalidos = [];
eventos.forEach((e, i) => {
